"""Frozen follow-up guards: a reverted run cannot mutate or be failed by cleanup."""
# ruff: noqa: E501

OLD_SCOPE_FAILED = "CREATE OR REPLACE FUNCTION kernel_scope_failed(rid uuid) RETURNS boolean\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$\n      DECLARE r agent_runs; cid uuid; prior_actor text; lost boolean;\n      BEGIN\n        SELECT * INTO r FROM agent_runs WHERE id=rid\n          AND tenant_id=NULLIF(current_setting('pdos.tenant_id',true),'')::uuid\n          AND requester_id=scope_requester() AND requester_id=scope_actor()\n          AND category_id IS NOT DISTINCT FROM\n            NULLIF(current_setting('pdos.category_id',true),'')::uuid FOR UPDATE;\n        IF NOT FOUND OR r.state IN ('completed','partial','failed','cancelled') THEN RETURN false; END IF;\n        prior_actor=current_setting('pdos.actor_id',true);\n        PERFORM set_config('pdos.actor_id',r.writer_id::text,true);\n        lost=NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=r.tenant_id\n            AND p.id=r.writer_id AND p.kind='agent' AND p.active)\n          OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=r.tenant_id\n            AND p.id=r.requester_id AND p.kind='human' AND p.active)\n          OR (r.category_id IS NOT NULL AND NOT category_access(r.tenant_id,r.category_id))\n          OR NOT kernel_read_set_visible(r.tenant_id,r.category_id,r.read_sources)\n          OR (r.validation_budget_id IS NOT NULL AND NOT EXISTS(\n            SELECT 1 FROM agent_validation_budgets b WHERE b.id=r.validation_budget_id\n              AND b.tenant_id=r.tenant_id AND b.active))\n          OR (r.product_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM products p\n            WHERE p.id=r.product_id AND p.tenant_id=r.tenant_id AND p.category_id=r.category_id\n              AND (p.visibility='category' OR p.owner_id=r.requester_id OR EXISTS(\n                SELECT 1 FROM object_audiences a WHERE a.tenant_id=p.tenant_id\n                  AND a.category_id=p.category_id AND a.object_type='products'\n                  AND a.subject_id=p.id AND a.owner_id=p.owner_id AND a.principal_id=r.requester_id))));\n        IF NOT COALESCE(lost,true) THEN\n          PERFORM set_config('pdos.actor_id',prior_actor,true); RETURN false;\n        END IF;\n        FOR cid IN SELECT id FROM agent_tool_calls WHERE tenant_id=r.tenant_id\n            AND run_id=r.id AND state='started' ORDER BY id LOOP\n          PERFORM kernel_release_call(r.id,cid,'FORBIDDEN_SCOPE',true,0,NULL);\n        END LOOP;\n        PERFORM set_config('pdos.actor_id',prior_actor,true);\n        UPDATE agent_runs SET state='failed',error_code='FORBIDDEN_SCOPE',result=NULL WHERE id=r.id;\n        RETURN true;\n      END $$"

SCOPE_FAILED = "CREATE OR REPLACE FUNCTION kernel_scope_failed(rid uuid) RETURNS boolean\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$\n      DECLARE r agent_runs; cid uuid; prior_actor text; lost boolean;\n      BEGIN\n        SELECT * INTO r FROM agent_runs WHERE id=rid\n          AND tenant_id=NULLIF(current_setting('pdos.tenant_id',true),'')::uuid\n          AND requester_id=scope_requester() AND requester_id=scope_actor()\n          AND category_id IS NOT DISTINCT FROM\n            NULLIF(current_setting('pdos.category_id',true),'')::uuid FOR UPDATE;\n        IF NOT FOUND OR r.reverted_at IS NOT NULL OR r.state IN ('completed','partial','failed','cancelled') THEN RETURN false; END IF;\n        prior_actor=current_setting('pdos.actor_id',true);\n        PERFORM set_config('pdos.actor_id',r.writer_id::text,true);\n        lost=NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=r.tenant_id\n            AND p.id=r.writer_id AND p.kind='agent' AND p.active)\n          OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=r.tenant_id\n            AND p.id=r.requester_id AND p.kind='human' AND p.active)\n          OR (r.category_id IS NOT NULL AND NOT category_access(r.tenant_id,r.category_id))\n          OR NOT kernel_read_set_visible(r.tenant_id,r.category_id,r.read_sources)\n          OR (r.validation_budget_id IS NOT NULL AND NOT EXISTS(\n            SELECT 1 FROM agent_validation_budgets b WHERE b.id=r.validation_budget_id\n              AND b.tenant_id=r.tenant_id AND b.active))\n          OR (r.product_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM products p\n            WHERE p.id=r.product_id AND p.tenant_id=r.tenant_id AND p.category_id=r.category_id\n              AND (p.visibility='category' OR p.owner_id=r.requester_id OR EXISTS(\n                SELECT 1 FROM object_audiences a WHERE a.tenant_id=p.tenant_id\n                  AND a.category_id=p.category_id AND a.object_type='products'\n                  AND a.subject_id=p.id AND a.owner_id=p.owner_id AND a.principal_id=r.requester_id))));\n        IF NOT COALESCE(lost,true) THEN\n          PERFORM set_config('pdos.actor_id',prior_actor,true); RETURN false;\n        END IF;\n        FOR cid IN SELECT id FROM agent_tool_calls WHERE tenant_id=r.tenant_id\n            AND run_id=r.id AND state='started' ORDER BY id LOOP\n          PERFORM kernel_release_call(r.id,cid,'FORBIDDEN_SCOPE',true,0,NULL);\n        END LOOP;\n        PERFORM set_config('pdos.actor_id',prior_actor,true);\n        UPDATE agent_runs SET state='failed',error_code='FORBIDDEN_SCOPE',result=NULL WHERE id=r.id;\n        RETURN true;\n      END $$"

RUN_GUARD = "CREATE OR REPLACE FUNCTION kernel_run_guard() RETURNS trigger LANGUAGE plpgsql AS $$\n    DECLARE s agent_sessions; BEGIN\n      IF TG_OP='UPDATE' THEN\n        IF NEW.tenant_id<>OLD.tenant_id OR NEW.id<>OLD.id OR NEW.session_id<>OLD.session_id\n        OR NEW.requester_id<>OLD.requester_id OR NEW.writer_id<>OLD.writer_id\n        OR NEW.category_id IS DISTINCT FROM OLD.category_id\n        OR NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.proposal_id IS DISTINCT FROM OLD.proposal_id\n        OR NEW.goal<>OLD.goal OR NEW.trigger<>OLD.trigger OR NEW.intent_key<>OLD.intent_key\n        OR NEW.intent_digest<>OLD.intent_digest OR NEW.private_context IS DISTINCT FROM OLD.private_context\n        OR NEW.data_categories IS DISTINCT FROM OLD.data_categories\n        OR NEW.customer_identities IS DISTINCT FROM OLD.customer_identities\n        OR NEW.cancel_epoch<OLD.cancel_epoch OR ((OLD.state IN ('completed','partial','failed','cancelled') AND NEW IS DISTINCT FROM OLD AND\n          (NEW.reverted_at IS NULL OR (to_jsonb(NEW)-ARRAY['cancel_epoch','reverted_at','reverted_by','revert_receipt_id'])\n          IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['cancel_epoch','reverted_at','reverted_by','revert_receipt_id'])))\n          OR (OLD.reverted_at IS NOT NULL AND NEW IS DISTINCT FROM OLD))\n        THEN RAISE EXCEPTION 'Kernel run binding immutable'; END IF;\n      ELSE\n        SELECT * INTO s FROM agent_sessions WHERE tenant_id=NEW.tenant_id AND id=NEW.session_id;\n        IF s.id IS NULL OR s.owner_id<>NEW.requester_id OR s.category_id IS DISTINCT FROM NEW.category_id\n        OR s.product_id IS DISTINCT FROM NEW.product_id OR s.proposal_id IS DISTINCT FROM NEW.proposal_id\n        OR NOT EXISTS(SELECT 1 FROM principals WHERE tenant_id=NEW.tenant_id AND id=NEW.writer_id\n                      AND kind='agent' AND active) THEN RAISE EXCEPTION 'Kernel run scope invalid'; END IF;\n      END IF;\n      IF NEW.held_tokens<0 OR NEW.used_tokens<0 OR NEW.token_limit<1 OR NEW.cancel_epoch<0\n      OR NEW.state NOT IN ('queued','running','waiting_input','completed','partial','failed','cancelled')\n      THEN RAISE EXCEPTION 'Kernel state invalid'; END IF;\n      RETURN NEW;\n    END $$"
